/* "Why Go to Sun State Trailers for Semi Trailer Parts" — the single-post layout.
   The same shell as the other long-form posts (the Post hero, Post contents and
   Share row components carry their own rules), plus the three shapes this
   article sets inside its prose: the bordered two-column lists, the checkmark
   lists and the 380px photo crops. Colour, type and spacing resolve through the
   design system, so nothing here hardcodes a brand value the Design screen
   cannot change.

   Almost every rule is prefixed with the column it belongs to: the site layer
   sets a post's prose at one size and these blocks are exceptions to it, so
   each has to outrank the prose rule rather than merely follow it. */

/* --- The article shell -----------------------------------------------------
   A 240px rail and the prose column, 64px apart, in a 1180px band — the gutter
   inside it, as the handoff measures it, so the prose runs about 780px. The spans the
   columns carry (3 and 9) are what the Design canvas and the stacked step below
   fall back to. */
[data-bz-node="article"].bz-section,
[data-bz-node="article"] > .bz-section { padding-block: 64px 0; }
[data-bz-node="article"].bz-section > .bz-container,
[data-bz-node="article"] > .bz-section > .bz-container { max-width: 1180px; }
[data-bz-node="art-row"] { grid-template-columns: 240px minmax(0, 1fr); gap: 64px; }
[data-bz-node="art-row"] > .bz-col { grid-column: auto; }
/* The rail travels with the prose: the column sticks as one, so the list and
   the promo card under it stay together. */
[data-bz-node="art-side"] { position: sticky; top: 24px; align-self: start; }

/* Every block inside the article sets its own rhythm with margins, the way the
   handoff's prose does, so the padding the site layer puts between stacked
   blocks is handed back rather than doubling every gap. */
[data-bz-node="art-body"] .bz-block,
[data-bz-node="art-body"] .bz-block + .bz-block,
[data-bz-node="art-side"] .bz-block,
[data-bz-node="art-side"] .bz-block + .bz-block { padding-block: 0; }
[data-bz-node="art-body"] .bz-text,
[data-bz-node="art-side"] .bz-text { max-width: none; }
[data-bz-node="art-body"] .bz-container,
[data-bz-node="art-side"] .bz-container { padding-inline: 0; max-width: none; }

/* --- The prose -------------------------------------------------------------
   17px/1.8 body against 28px headings, with the lede a step up in ink. The
   headings carry the ids the rail links to, so each keeps a scroll margin. */
[data-bz-node="art-body"] .bz-block--heading h2 {
  font-size: 28px; line-height: 1.22; letter-spacing: -0.01em;
  margin: 52px 0 16px; scroll-margin-top: 24px;
}
[data-bz-node="art-body"] .bz-block--text p {
  font-size: 17px; line-height: 1.8; color: var(--body-text); margin: 0 0 18px;
}
[data-bz-node="art-body"] .bz-block--text strong { color: var(--ink); }
[data-bz-node="art-body"] [data-bz-node="lede"] p { font-size: 19px; color: var(--ink); }
[data-bz-node="art-body"] .bz-block--text a { color: var(--accent); }

/* --- Quick answer, the rail's promo card, the callout ---------------------- */
[data-bz-node="art-body"] [data-bz-node="qa-label"] p,
[data-bz-node="art-side"] [data-bz-node="aside-label"] p {
  font: 700 var(--text-eyebrow) / 1.2 var(--font-body);
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--accent); margin: 0 0 14px;
}
/* The answer-engine target: one paragraph, no list and no links, in a grey
   block with the accent rule down its left edge. */
[data-bz-node="qa"] {
  background: var(--paper); border-left: 3px solid var(--accent);
  padding: 24px 26px; margin-bottom: 38px;
}
[data-bz-node="art-body"] [data-bz-node="qa-body"] p {
  font-size: 16px; line-height: 1.75; color: var(--ink); margin: 0;
}
[data-bz-node="art-aside"] { border: 1px solid var(--line); padding: 20px; margin-top: 26px; }
[data-bz-node="art-side"] [data-bz-node="aside-body"] p {
  font-size: 14px; line-height: 1.65; color: var(--body-text); margin: 0 0 14px;
}
[data-bz-node="callout"] { border: 1px solid var(--line); padding: 26px 28px; margin: 34px 0; }
[data-bz-node="aside-cta"] .bz-btns,
[data-bz-node="callout-cta"] .bz-btns { margin-block: 0; }
[data-bz-node="art-body"] [data-bz-node="callout-cta"] .bz-btn--link,
[data-bz-node="art-side"] [data-bz-node="aside-cta"] .bz-btn--link { font-size: 15px; font-weight: 700; }

/* --- Two-column lists -------------------------------------------------------
   Two bordered cards side by side, each a real bulleted list. */
[data-bz-node="parts-cards"],
[data-bz-node="checklist-cards"] { gap: 28px; margin-bottom: 20px; }
[data-bz-node="parts-cards"] > .bz-col,
[data-bz-node="checklist-cards"] > .bz-col { border: 1px solid var(--line); padding: 22px; }
[data-bz-node="art-body"] .ss-prose-list { margin: 0; padding-left: 20px; max-width: none; }
[data-bz-node="art-body"] .ss-prose-list li { font-size: 16px; line-height: 1.75; margin: 0 0 6px; }
[data-bz-node="art-body"] .ss-prose-list li:last-child { margin-bottom: 0; }

/* --- Photographs ------------------------------------------------------------
   Cropped to 380px (240px at phone width), whatever the upload's proportions. */
[data-bz-node="fig-team"],
[data-bz-node="fig-inventory"] { margin: 36px 0; }
[data-bz-node="fig-team"] .bz-figure,
[data-bz-node="fig-inventory"] .bz-figure { margin: 0; }
[data-bz-node="fig-team"] img,
[data-bz-node="fig-inventory"] img { width: 100%; height: 380px; object-fit: cover; display: block; border-radius: 0; }

/* --- Actions ----------------------------------------------------------------
   The outline button is drawn in ink, as the handoff's dark ghost button. */
[data-bz-node="art-actions"] .bz-btns { gap: 14px; margin: 40px 0 8px; }
[data-bz-node="art-actions"] .bz-btn--secondary { background: transparent; color: var(--ink); border-color: var(--ink); }
[data-bz-node="art-actions"] .bz-btn--secondary:hover { background: var(--ink); color: #fff; }

@media (prefers-reduced-motion: no-preference) {
  html:has([data-bz-node="art-toc"]) { scroll-behavior: smooth; }
}

/* --- FAQ ------------------------------------------------------------------- */
[data-bz-node="faq"].bz-section,
[data-bz-node="faq"] > .bz-section { padding-block: 90px; }

/* --- Related posts ---------------------------------------------------------
   The platform's Latest posts block, resolved from the Posts screen at build
   time. It has no way to leave out the post being read, so it asks for four
   and this post's own card is hidden; when the post is not among the latest
   four, the fourth card is the one hidden. Either way three cards show. */
[data-bz-node="related"].bz-section,
[data-bz-node="related"] > .bz-section { padding-block: 90px; }
[data-bz-node="related-h"] h2 { font-size: 28px; margin: 0 0 34px; }
[data-bz-node="related-posts"] .bz-sechead { display: none; }
[data-bz-node="related-posts"] .bz-grid { gap: 24px; grid-template-columns: repeat(3, minmax(0, 1fr)); }
[data-bz-node="related-posts"] .bz-card[href*="/why-go-to-sun-state-trailers-for-semi-trailer-parts"] { display: none; }
[data-bz-node="related-posts"] .bz-grid:not(:has(.bz-card[href*="/why-go-to-sun-state-trailers-for-semi-trailer-parts"])) > .bz-card:nth-child(n+4) { display: none; }
[data-bz-node="related-posts"] .bz-card { border: 1px solid var(--line); background: var(--card); }
[data-bz-node="related-posts"] .bz-card img,
[data-bz-node="related-posts"] .bz-card .bz-photo { height: 180px; aspect-ratio: auto; object-fit: cover; }
[data-bz-node="related-posts"] .bz-card__body { padding: 24px 22px 26px; gap: 0; }
[data-bz-node="related-posts"] .bz-card__m { font-size: 12px; color: var(--muted); margin-bottom: 12px; }
[data-bz-node="related-posts"] .bz-card__t {
  font: 700 19px / 1.3 var(--font-heading); color: var(--ink); text-transform: none; margin-bottom: 12px;
}
/* The handoff's cards carry the date and the title only. */
[data-bz-node="related-posts"] .bz-post__d { display: none; }
/* The whole card is the link, so the handoff's "Read more →" is drawn rather
   than authored as a second anchor to the same destination. */
[data-bz-node="related-posts"] .bz-card__body::after {
  content: "Read more \2192"; font: 700 14px / 1 var(--font-body); color: var(--accent); margin-top: 18px;
}
[data-bz-node="related-posts"] .bz-card:hover .bz-card__t { color: var(--accent); }
[data-bz-node="related-cta"] .bz-btns { margin: 34px 0 0; }
[data-bz-node="related-cta"] .bz-btn--link { font-size: 15px; font-weight: 700; }

/* --- The two steps the handoff takes --------------------------------------- */
@media (max-width: 1100px) {
  [data-bz-node="art-row"] { grid-template-columns: minmax(0, 1fr); gap: 36px; }
  [data-bz-node="art-side"] { position: static; }
  [data-bz-node="art-aside"] { margin-top: 20px; }
  [data-bz-node="related-posts"] .bz-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 640px) {
  [data-bz-node="article"].bz-section,
  [data-bz-node="article"] > .bz-section { padding-block: 40px 0; }
  [data-bz-node="art-body"] .bz-block--heading h2 { font-size: 23px; margin-top: 40px; }
  [data-bz-node="art-body"] [data-bz-node="lede"] p { font-size: 17px; }
  [data-bz-node="parts-cards"],
  [data-bz-node="checklist-cards"] { grid-template-columns: minmax(0, 1fr); }
  [data-bz-node="parts-cards"] > .bz-col,
  [data-bz-node="checklist-cards"] > .bz-col { grid-column: auto; }
  [data-bz-node="fig-team"] img,
  [data-bz-node="fig-inventory"] img { height: 240px; }
  [data-bz-node="related-posts"] .bz-grid { grid-template-columns: minmax(0, 1fr); }
  [data-bz-node="faq"].bz-section,
  [data-bz-node="faq"] > .bz-section,
  [data-bz-node="related"].bz-section,
  [data-bz-node="related"] > .bz-section { padding-block: 64px; }
}

